import 'package:shared_preferences/shared_preferences.dart';\n\nclass LocalStorageService {\n  static final LocalStorageService _instance = LocalStorageService._internal();\n\n  factory LocalStorageService() {\n    return _instance;\n  }\n\n  LocalStorageService._internal();\n\n  late SharedPreferences _prefs;\n\n  Future<void> init() async {\n    _prefs = await SharedPreferences.getInstance();\n  }\n\n  Future<void> saveFavorite(String toolId) async {\n    final favorites = getFavorites();\n    if (!favorites.contains(toolId)) {\n      favorites.add(toolId);\n      await _prefs.setStringList('favorites', favorites);\n    }\n  }\n\n  Future<void> removeFavorite(String toolId) async {\n    final favorites = getFavorites();\n    favorites.remove(toolId);\n    await _prefs.setStringList('favorites', favorites);\n  }\n\n  List<String> getFavorites() {\n    return _prefs.getStringList('favorites') ?? [];\n  }\n\n  bool isFavorite(String toolId) {\n    return getFavorites().contains(toolId);\n  }\n\n  Future<void> addRecentlyViewed(String toolId) async {\n    final recently = getRecentlyViewed();\n    recently.removeWhere((id) => id == toolId);\n    recently.insert(0, toolId);\n    if (recently.length > 20) {\n      recently.removeRange(20, recently.length);\n    }\n    await _prefs.setStringList('recently_viewed', recently);\n  }\n\n  List<String> getRecentlyViewed() {\n    return _prefs.getStringList('recently_viewed') ?? [];\n  }\n\n  Future<void> setThemeMode(String mode) async {\n    await _prefs.setString('theme_mode', mode);\n  }\n\n  String getThemeMode() {\n    return _prefs.getString('theme_mode') ?? 'system';\n  }\n\n  Future<void> setLanguage(String language) async {\n    await _prefs.setString('language', language);\n  }\n\n  String getLanguage() {\n    return _prefs.getString('language') ?? 'en';\n  }\n\n  Future<void> setCache(String key, String value) async {\n    await _prefs.setString(key, value);\n  }\n\n  String? getCache(String key) {\n    return _prefs.getString(key);\n  }\n\n  Future<void> clearCache(String key) async {\n    await _prefs.remove(key);\n  }\n\n  Future<void> clearAllCache() async {\n    await _prefs.clear();\n  }\n}\n